CREATE TABLE el_suppliers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_inventory_items(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,sku TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'unit',reorder_level INTEGER NOT NULL DEFAULT 0 CHECK(reorder_level>=0),unit_cost INTEGER NOT NULL DEFAULT 0 CHECK(unit_cost>=0),sale_price INTEGER NOT NULL DEFAULT 0 CHECK(sale_price>=0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(org_id,id),UNIQUE(org_id,sku));
CREATE TABLE el_stock_balances(org_id TEXT NOT NULL,branch_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),PRIMARY KEY(branch_id,item_id),FOREIGN KEY(org_id,item_id) REFERENCES el_inventory_items(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_stock_movements(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity<>0),kind TEXT NOT NULL CHECK(kind IN ('receipt','adjustment','transfer_in','transfer_out','sale','return')),reference_id TEXT,reason TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),UNIQUE(org_id,idempotency_key),FOREIGN KEY(org_id,item_id) REFERENCES el_inventory_items(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_stock_apply AFTER INSERT ON el_stock_movements BEGIN INSERT INTO el_stock_balances(org_id,branch_id,item_id,quantity) VALUES(NEW.org_id,NEW.branch_id,NEW.item_id,0) ON CONFLICT(branch_id,item_id) DO NOTHING; UPDATE el_stock_balances SET quantity=quantity+NEW.quantity WHERE branch_id=NEW.branch_id AND item_id=NEW.item_id; END;
CREATE TRIGGER el_stock_immutable BEFORE UPDATE ON el_stock_movements BEGIN SELECT RAISE(ABORT,'Stock movements are immutable');END;
CREATE TRIGGER el_stock_no_delete BEFORE DELETE ON el_stock_movements WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Stock movements cannot be deleted');END;
CREATE TABLE el_purchase_orders(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,supplier_id TEXT NOT NULL,number TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ordered','received','cancelled')),total INTEGER NOT NULL CHECK(total>0),ordered_by TEXT,received_by TEXT,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),UNIQUE(org_id,number),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,supplier_id) REFERENCES el_suppliers(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE TABLE el_purchase_lines(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,order_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_cost INTEGER NOT NULL CHECK(unit_cost>=0),is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(order_id,item_id),FOREIGN KEY(org_id,order_id) REFERENCES el_purchase_orders(org_id,id),FOREIGN KEY(org_id,item_id) REFERENCES el_inventory_items(org_id,id));
CREATE TRIGGER el_purchase_lock BEFORE UPDATE ON el_purchase_orders BEGIN SELECT CASE WHEN NEW.total<>OLD.total OR NEW.branch_id<>OLD.branch_id OR NEW.supplier_id<>OLD.supplier_id OR NOT((OLD.status='draft' AND NEW.status IN ('ordered','cancelled')) OR (OLD.status='ordered' AND NEW.status IN ('received','cancelled'))) THEN RAISE(ABORT,'Purchase order transition is invalid') END;END;
CREATE TABLE el_stock_transfers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,from_branch TEXT NOT NULL,to_branch TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),requested_by TEXT NOT NULL,decided_by TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,CHECK(from_branch<>to_branch),UNIQUE(org_id,id),FOREIGN KEY(org_id,from_branch) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,to_branch) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,item_id) REFERENCES el_inventory_items(org_id,id),FOREIGN KEY(org_id,requested_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_stock_transfer_lock BEFORE UPDATE ON el_stock_transfers BEGIN SELECT CASE WHEN OLD.status<>'pending' OR NEW.status NOT IN ('approved','rejected') OR NEW.requested_by=NEW.decided_by OR NEW.from_branch<>OLD.from_branch OR NEW.to_branch<>OLD.to_branch OR NEW.quantity<>OLD.quantity OR NEW.item_id<>OLD.item_id THEN RAISE(ABORT,'Stock transfer requires an independent pending decision') END;END;
CREATE TABLE el_assets(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,item_id TEXT,code TEXT NOT NULL,name TEXT NOT NULL,serial TEXT NOT NULL DEFAULT '',employee_id TEXT,location TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','assigned','maintenance','retired')),purchased_on TEXT NOT NULL DEFAULT '',value INTEGER NOT NULL DEFAULT 0 CHECK(value>=0),is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(org_id,id),UNIQUE(org_id,code),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,item_id) REFERENCES el_inventory_items(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES el_employees(org_id,id));
CREATE TABLE el_asset_events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,asset_id TEXT NOT NULL,kind TEXT NOT NULL,notes TEXT NOT NULL,cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0),created_by TEXT NOT NULL,created_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(org_id,asset_id) REFERENCES el_assets(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_supplier_branch ON el_suppliers(org_id,branch_id,name);
CREATE INDEX el_stock_item ON el_stock_movements(org_id,branch_id,item_id,created_at);
CREATE INDEX el_inventory_lookup ON el_inventory_items(org_id,status,name);
CREATE INDEX el_purchase_branch ON el_purchase_orders(org_id,branch_id,status,date);
CREATE INDEX el_transfers_branches ON el_stock_transfers(org_id,from_branch,to_branch,status);
CREATE INDEX el_assets_branch ON el_assets(org_id,branch_id,status,name);
CREATE INDEX el_asset_events_lookup ON el_asset_events(org_id,asset_id,created_at);
CREATE TABLE el_stock_sales(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,invoice_id TEXT NOT NULL,student_id TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>0),status TEXT NOT NULL DEFAULT 'dispatched' CHECK(status IN ('dispatched','returned')),created_by TEXT NOT NULL,returned_by TEXT,created_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),UNIQUE(invoice_id),FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE TABLE el_stock_sale_lines(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,sale_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(sale_id,item_id),FOREIGN KEY(org_id,sale_id) REFERENCES el_stock_sales(org_id,id),FOREIGN KEY(org_id,item_id) REFERENCES el_inventory_items(org_id,id));
CREATE TRIGGER el_stock_sale_invoice BEFORE INSERT ON el_stock_sales BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoices WHERE id=NEW.invoice_id AND org_id=NEW.org_id AND branch_id=NEW.branch_id AND student_id=NEW.student_id AND status='issued' AND total>=NEW.total) THEN RAISE(ABORT,'Stock sale requires an issued matching invoice') END;END;
CREATE TRIGGER el_stock_sale_return BEFORE UPDATE ON el_stock_sales BEGIN SELECT CASE WHEN OLD.status<>'dispatched' OR NEW.status<>'returned' OR NEW.total<>OLD.total OR NEW.invoice_id<>OLD.invoice_id OR NEW.branch_id<>OLD.branch_id OR NEW.student_id<>OLD.student_id THEN RAISE(ABORT,'Stock sale can only return once') END;END;
CREATE INDEX el_stock_sales_branch ON el_stock_sales(org_id,branch_id,created_at);
CREATE TRIGGER el_purchase_line_lock BEFORE UPDATE ON el_purchase_lines BEGIN SELECT RAISE(ABORT,'Purchase order lines are immutable');END;
CREATE TRIGGER el_stock_sale_line_lock BEFORE UPDATE ON el_stock_sale_lines BEGIN SELECT RAISE(ABORT,'Stock sale lines are immutable');END;
CREATE TABLE el_asset_transfers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,asset_id TEXT NOT NULL,from_branch TEXT NOT NULL,to_branch TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),notes TEXT NOT NULL,requested_by TEXT NOT NULL,decided_by TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(org_id,id),CHECK(from_branch<>to_branch),FOREIGN KEY(org_id,asset_id) REFERENCES el_assets(org_id,id),FOREIGN KEY(org_id,from_branch) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,to_branch) REFERENCES el_branches(org_id,id));
CREATE UNIQUE INDEX el_asset_transfer_pending ON el_asset_transfers(asset_id) WHERE status='pending';
CREATE TRIGGER el_asset_transfer_lock BEFORE UPDATE ON el_asset_transfers BEGIN SELECT CASE WHEN OLD.status<>'pending' OR NEW.status NOT IN ('approved','rejected') OR NEW.requested_by=NEW.decided_by OR NEW.from_branch<>OLD.from_branch OR NEW.to_branch<>OLD.to_branch OR NEW.asset_id<>OLD.asset_id THEN RAISE(ABORT,'Asset transfer requires an independent pending decision') END;SELECT CASE WHEN NEW.status='approved' AND NOT EXISTS(SELECT 1 FROM el_assets WHERE id=OLD.asset_id AND branch_id=OLD.from_branch AND status='available') THEN RAISE(ABORT,'Asset is not available in the source branch') END;END;
CREATE TRIGGER el_asset_transfer_apply AFTER UPDATE ON el_asset_transfers WHEN NEW.status='approved' BEGIN UPDATE el_assets SET branch_id=NEW.to_branch,location='',employee_id=NULL WHERE id=NEW.asset_id;END;
CREATE INDEX el_asset_transfers_lookup ON el_asset_transfers(org_id,asset_id,status,created_at);
